<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';require_role(['admin']);
$id=max(0,(int)($_GET['id']??$_POST['id']??0));$st=db()->prepare('SELECT * FROM personnel WHERE id=?');$st->execute([$id]);$p=$st->fetch();if(!$p){flash('danger','پرسنل پیدا نشد.');redirect('personnel.php');}$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$first=trim((string)$_POST['first_name']);$last=trim((string)$_POST['last_name']);$national=preg_replace('/\\D+/','',(string)$_POST['national_id']);$mobile=trim((string)$_POST['mobile']);if($first===''||$last===''||!preg_match('/^\\d{10}$/',$national))throw new RuntimeException('نام، نام خانوادگی و کدملی ۱۰ رقمی الزامی است.');$q=db()->prepare('SELECT id FROM personnel WHERE national_id=? AND id<>?');$q->execute([$national,$id]);if($q->fetchColumn())throw new RuntimeException('این کدملی قبلاً ثبت شده است.');$q=db()->prepare('UPDATE personnel SET first_name=?,last_name=?,national_id=?,full_name=?,mobile=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');$q->execute([$first,$last,$national,$first.' '.$last,$mobile,$id]);audit('personnel_updated','personnel',(string)$id,['national_id'=>$national]);flash('success','اطلاعات پرسنل به‌روزرسانی شد.');redirect('personnel.php');}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ویرایش پرسنل</title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">سامانه سخت‌افزار</a><nav><a href="personnel.php">پرسنل</a><a href="assets.php">تجهیزات</a><a href="logout.php">خروج</a></nav></header><main><div class="page-head"><h1>ویرایش پرسنل</h1></div><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><form method="post" class="panel form-grid"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><label>نام<input name="first_name" value="<?=e($p['first_name']??'')?>" required></label><label>نام خانوادگی<input name="last_name" value="<?=e($p['last_name']??'')?>" required></label><label>کدملی<input name="national_id" value="<?=e($p['national_id']??'')?>" maxlength="10" required></label><label>تلفن همراه<input name="mobile" value="<?=e($p['mobile']??'') ?>"></label><div class="actions"><button class="btn primary">ذخیره</button><a class="btn" href="personnel.php">انصراف</a></div></form></main></body></html>
